# drawdown curvature: recent drawdown improvement vs prior drawdown, risk normalized
hi=c.rolling(120,min_periods=80).max(); dd=c/hi-1
f=((dd.shift(1)-dd.shift(11))/(v.shift(1)*np.sqrt(10))).shift(1)
for h in [1,5,10]:
 y=c.shift(-h)/c-1; a=[];ns=[]; tr=[]; prev=None
