        # cross-sectional rank turnover versus prior valid day
        if d in F.index and len(F.loc[d].dropna())>=8:
            prev=F.loc[:d].iloc[:-1].dropna(how='all').tail(1)
            if len(prev):
                q=pd.concat([F.loc[d],prev.iloc[0]],axis=1).dropna()
                if len(q)>=8: turnovers.append((q.iloc[:,0].rank().corr(q.iloc[:,1].rank())))
    x=pd.Series(dict(obs)).sort_index(); ic=x.mean(); sd=x.std(ddof=1); ir=ic/sd if sd else np.nan
    hit=(x>0).mean(); turn=np.nanmean([1-v for v in turnovers]) if turnovers else np.nan
    print(name,'dates',len(x),'avgN',round(np.mean(ns),2),'IC',round(ic,6),'ICIR',round(ir,6),'hit',round(hit,4),'turn',round(turn,4),'coverage',round(len(x)/(len(px)-1),4))
    for label,lo,hi in [('pre',x.index.min(),pd.Timestamp('2026-12-31')),('2027_28',pd.Timestamp('2027-01-01'),pd.Timestamp('2028-12-31')),('2029',pd.Timestamp('2029-01-01'),x.index.max())]:
        y=x[(x.index>=lo)&(x.index<=hi)]
        if len(y)>5: print(' ',label,len(y),round(y.mean(),6),round(y.mean()/y.std(ddof=1),6))
