r=f.rank(axis=1,pct=True); print('turnover_proxy %.6f coverage %.6f'%((r.diff().abs().mean(axis=1)).mean(),f.notna().sum().sum()/f.size))
for start in ['2028-01-01','2029-01-01','2029-07-01']:
