neg=r.where(r<0); dd=np.sqrt((neg**2).rolling(30).mean()); f=(r.rolling(15).sum()/(dd*np.sqrt(15)+1e-6)).shift(1)
ics=[]; dec={h:[] for h in [1,3,5,10]}
